head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf05003";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_datefmt_cal_isuPrcDecsnBasDd();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf05003.onpageload' });
    }
};

/**
 * @method
 * @name init_datefmt_cal_isuPrcDecsnBasDd
 * @description 초기화 — datefmt cal isu Prc Decsn Bas Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_isuPrcDecsnBasDd = function () { $c.date.checkCalendarFormat("cal_isuPrcDecsnBasDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.makeInputFromParent();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05003.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldbnf05003: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_isuPrcDecsnBasInt_onchange
 * @description slc_isuPrcDecsnBasInt 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_isuPrcDecsnBasInt_onchange = async function(e){
    try {
        await scwin.Etc_select();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05003.slc_isuPrcDecsnBasInt_onchange' }); }
};

/**
 * @method
 * @name ipt_isuPrcMiscBasIntContn_onpaste
 * @description ipt_isuPrcMiscBasIntContn onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_isuPrcMiscBasIntContn_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05003.ipt_isuPrcMiscBasIntContn_onpaste' }); }
};

/**
 * @method
 * @name ipt_isuPrcDecsnSpd_onpaste
 * @description ipt_isuPrcDecsnSpd onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_isuPrcDecsnSpd_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05003.ipt_isuPrcDecsnSpd_onpaste' }); }
};

/**
 * @method
 * @name btn_iStdIntForm_onclick
 * @description btn_iStdIntForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_iStdIntForm_onclick = async function(e){
    try {
        await scwin.i_std_int_form('ok')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05003.btn_iStdIntForm_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05003.btn_self_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name makeInputFromParent
 * @description make Input From Parent 처리
 * @returns {void}
 * @hidden N
 */
scwin.makeInputFromParent = function () {

    const parentfm = ((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] !== undefined ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] : undefined);
    const fm = (document.InputForm || { elements: [] });
    $c.util.getComponent("slc_isuPrcDecsnBasInt").setValue(parentfm.isu_prc_decsn_bas_int.value);
    let v_str = parentfm.coupn_rt_decsn_bas_int_cd.value;
    if (v_str === '90') {
        $c.util.getComponent('ipt_isuPrcMiscBasIntContn').setDisabled(false);
    }
    $c.util.getComponent("slc_isuPrcDecsnRemainPdCd").setValue(parentfm.isu_prc_decsn_remain_pd_cd.value);
    $c.util.getComponent("slc_isuPrcDecsnSpdSgn").setValue(parentfm.isu_prc_decsn_spd_sgn.value);
    $c.util.getComponent("ipt_isuPrcDecsnSpd").setValue(parentfm.isu_prc_decsn_spd.value);
    $c.util.getComponent("cal_isuPrcDecsnBasDd").setValue(parentfm.isu_prc_decsn_bas_dd.value);
    $c.util.getComponent("ipt_isuPrcDecsnTm").setValue(parentfm.isu_prc_decsn_tm.value);
    v_str = parentfm.isu_prc_decsn_tm.value;
    if (v_str === '1') {
        /* 수동 전환 필요: isu_prc_decsn_tm[0] 선택 — 옵션표 미해결 */ void 0;
    } else {
        if (v_str === '2') {
            /* 수동 전환 필요: isu_prc_decsn_tm[1] 선택 — 옵션표 미해결 */ void 0;
        }
    }
    $c.util.getComponent("ipt_isuPrcMiscBasIntContn").setValue(parentfm.isu_prc_misc_bas_int_contn.value);
};

/**
 * @method
 * @name Etc_select
 * @description Etc select 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.Etc_select = async function () {
    const fm = (document.InputForm || { elements: [] });
    if ($c.util.getComponent('slc_isuPrcDecsnBasInt').getValue() === '90') {
        $c.util.getComponent('ipt_isuPrcMiscBasIntContn').setDisabled(false);
        await $c.win.alert('기준금리를 기타선택시 \n\r기타 기준금리 항목만 입력하십시오.');
        $c.util.getComponent("slc_isuPrcDecsnRemainPdCd").setValue('');
        $c.util.getComponent("slc_isuPrcDecsnSpdSgn").setValue('');
        $c.util.getComponent("ipt_isuPrcDecsnSpd").setValue('');
        $c.util.getComponent("cal_isuPrcDecsnBasDd").setValue('');
        /* 수동 전환 필요: isu_prc_decsn_tm[0] 선택 해제 — 웹스퀘어 그룹 등가 미정 */ void 0;
        /* 수동 전환 필요: isu_prc_decsn_tm[1] 선택 해제 — 웹스퀘어 그룹 등가 미정 */ void 0;
        $c.util.getComponent('ipt_isuPrcDecsnTm').setItemDisabled(0, !!(true));
        $c.util.getComponent('ipt_isuPrcDecsnTm').setItemDisabled(1, !!(true));
        $c.util.getComponent('slc_isuPrcDecsnRemainPdCd').setDisabled(true);
        $c.util.getComponent('slc_isuPrcDecsnSpdSgn').setDisabled(true);
        $c.util.getComponent('ipt_isuPrcDecsnSpd').setDisabled(true);
        $c.util.getComponent('cal_isuPrcDecsnBasDd').setDisabled(true);
        $c.util.getComponent("ipt_isuPrcMiscBasIntContn").focus();
    } else {
        $c.util.getComponent('slc_isuPrcDecsnRemainPdCd').setDisabled(false);
        $c.util.getComponent('slc_isuPrcDecsnSpdSgn').setDisabled(false);
        $c.util.getComponent('ipt_isuPrcDecsnSpd').setDisabled(false);
        $c.util.getComponent('cal_isuPrcDecsnBasDd').setDisabled(false);
        $c.util.getComponent('ipt_isuPrcDecsnTm').setItemDisabled(0, !!(false));
        $c.util.getComponent('ipt_isuPrcDecsnTm').setItemDisabled(1, !!(false));
        $c.util.getComponent('ipt_isuPrcMiscBasIntContn').setDisabled(true);
        $c.util.getComponent("ipt_isuPrcMiscBasIntContn").setValue('');
    }
};

/**
 * @method
 * @name data_Chk
 * @description data Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.data_Chk = async function () {
    const fm = (document.InputForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('slc_isuPrcDecsnBasInt').getValue()) === 0) {
        await $c.win.alert('발행가액결정 기준금리를 선택하십시오.');
        $c.util.getComponent("slc_isuPrcDecsnBasInt").focus();
        return false;
    }
    if ($c.util.getComponent('slc_isuPrcDecsnBasInt').getValue() !== '90') {
        if ($c.str.getByteLength($c.util.getComponent('slc_isuPrcDecsnSpdSgn').getValue()) === 0) {
            await $c.win.alert('발행가액결정 가산금리의 기호를 선택하십시오.');
            $c.util.getComponent("slc_isuPrcDecsnSpdSgn").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_isuPrcDecsnSpd').getValue()) === 0) {
            await $c.win.alert('발행가액결정 가산금리를 입력하십시오.');
            $c.util.getComponent("ipt_isuPrcDecsnSpd").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('cal_isuPrcDecsnBasDd').getValue()) === 0) {
            await $c.win.alert('발행가액결정 기준일을 입력하십시오.');
            $c.util.getComponent("cal_isuPrcDecsnBasDd").focus();
            return false;
        }
        if (!($c.util.getComponent('ipt_isuPrcDecsnTm').getValue() !== '') && !($c.util.getComponent('ipt_isuPrcDecsnTm_2').getValue() !== '')) {
            await $c.win.alert('발행가액결정을 선택하십시오.');
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_isuPrcMiscBasIntContn').getValue()) > 0) {
            await $c.win.alert('기준금리를 기타선택시만 입력항목입니다.');
            $c.util.getComponent("ipt_isuPrcMiscBasIntContn").focus();
            return false;
        }
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_isuPrcMiscBasIntContn').getValue()) === 0) {
            await $c.win.alert('기타 기준금리를 선택하십시오.');
            $c.util.getComponent("ipt_isuPrcMiscBasIntContn").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_isuPrcMiscBasIntContn').getValue()) > 20) {
            await $c.win.alert('기타 기준금리를 한글 10자, 영문 20자 이내로 입력하십시오.');
            $c.util.getComponent("ipt_isuPrcMiscBasIntContn").focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name i_std_int_form
 * @description i std int form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.i_std_int_form = async function () {
    const fm = (document.InputForm || { elements: [] });
    if (!await scwin.data_Chk()) {
        return;
    }

    const parentfm = ((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] !== undefined ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] : undefined);
    $c.util.getComponent("slc_isuPrcDecsnBasInt").setValue($c.util.getComponent('slc_isuPrcDecsnBasInt').getValue());
    $c.util.getComponent("slc_isuPrcDecsnRemainPdCd").setValue($c.util.getComponent('slc_isuPrcDecsnRemainPdCd').getValue());
    $c.util.getComponent("slc_isuPrcDecsnSpdSgn").setValue($c.util.getComponent('slc_isuPrcDecsnSpdSgn').getValue());
    $c.util.getComponent("ipt_isuPrcDecsnSpd").setValue($c.util.getComponent('ipt_isuPrcDecsnSpd').getValue());
    $c.util.getComponent("cal_isuPrcDecsnBasDd").setValue($c.util.getComponent('cal_isuPrcDecsnBasDd').getValue());
    if (($c.util.getComponent('ipt_isuPrcDecsnTm').getValue() !== '')) {
        $c.util.getComponent("ipt_isuPrcDecsnTm").setValue('1');
    } else {
        if (($c.util.getComponent('ipt_isuPrcDecsnTm_2').getValue() !== '')) {
            $c.util.getComponent("ipt_isuPrcDecsnTm").setValue('2');
        }
    }
    $c.util.getComponent("ipt_isuPrcMiscBasIntContn").setValue($c.util.getComponent('ipt_isuPrcMiscBasIntContn').getValue());
    parentfm.isu_prc_save_yn.value = "Y";
    parent.$c.win.closePopup();
};
